1	import { OrderStatus } from "@prisma/client";
2	import { getCurrentUser } from "@/lib/auth";
3	import { z } from "zod";
4	import { prisma } from "@/lib/prisma";
5	
6	async function ensureAdmin() {
7	  const user = await getCurrentUser();
8	  if (!user || user.role !== "ADMIN") {
9	    throw new Error("Accès refusé. Privilèges administrateur requis.");
10	  }
11	  return user;
12	}
13	
14	// 1. Product & Category Administration
15	export const AdminProductSchema = z.object({
16	  titleFr: z.string().min(2),
17	  titleAr: z.string().min(2),
18	  descriptionFr: z.string().min(5),
19	  descriptionAr: z.string().min(5),
20	  price: z.coerce.number().min(0.01),
21	  oldPrice: z.coerce.number().min(0).optional(),
22	  categoryId: z.string().uuid(),
23	  isActive: z.boolean().default(true),
24	  isFeatured: z.boolean().default(false),
25	  stock: z.coerce.number().int().min(0),
26	});
27	
28	export async function adminCreateProduct(rawInput: unknown) {
29	  await ensureAdmin();
30	  const parsed = AdminProductSchema.parse(rawInput);
31	
32	  const slug = parsed.titleFr
33	    .toLowerCase()
34	    .replace(/[^a-z0-9]+/g, "-")
35	    .replace(/(^-|-$)+/g, "");
36	
37	  return await prisma.$transaction(async (tx) => {
38	    const product = await tx.product.create({
39	      data: {
40	        slug: `${slug}-${Date.now().toString().slice(-4)}`,
41	        titleFr: parsed.titleFr,
42	        titleAr: parsed.titleAr,
43	        descriptionFr: parsed.descriptionFr,
44	        descriptionAr: parsed.descriptionAr,
45	        price: parsed.price,
46	        oldPrice: parsed.oldPrice || null,
47	        categoryId: parsed.categoryId,
48	        isActive: parsed.isActive,
49	        isFeatured: parsed.isFeatured,
50	        inventory: {
51	          create: { stock: parsed.stock },
52	        },
53	        variants: {
54	          create: [
55	            {
56	              nameFr: "Standard",
57	              nameAr: "قياسي",
58	              sku: `SKU-${Date.now()}`,
59	              price: parsed.price,
60	              stock: parsed.stock,
61	            },
62	          ],
63	        },
64	      },
65	      include: { inventory: true, variants: true, category: true },
66	    });
67	
68	    return product;
69	  });
70	}
71	
72	export async function adminUpdateInventory(productId: string, newStock: number) {
73	  await ensureAdmin();
74	
75	  return await prisma.$transaction(async (tx) => {
76	    await tx.inventory.update({
77	      where: { productId },
78	      data: { stock: newStock },
79	    });
80	
81	    // Update primary variant stock as well
82	    await tx.productVariant.updateMany({
83	      where: { productId },
84	      data: { stock: newStock },
85	    });
86	
87	    return { success: true, newStock };
88	  });
89	}
90	
91	// 2. Order Management & Audit-safe Operations
92	export async function adminGetOrders() {
93	  await ensureAdmin();
94	
95	  return await prisma.order.findMany({
96	    include: {
97	      items: {
98	        include: { product: true, variant: true },
99	      },
100	      user: true,
101	    },
102	    orderBy: { createdAt: "desc" },
103	  });
104	}
105	
106	export async function adminUpdateOrderStatus(orderId: string, newStatus: OrderStatus) {
107	  const admin = await ensureAdmin();
108	
109	  const order = await prisma.order.findUnique({ where: { id: orderId } });
110	  if (!order) {
111	    throw new Error("Commande introuvable");
112	  }
113	
114	  // Audit log notation in notes
115	  const auditNote = `[Audit] Statut changé de ${order.status} à ${newStatus} par Admin (${admin.email}) le ${new Date().toISOString()}`;
116	  const existingNotes = order.notes ? `${order.notes}\n${auditNote}` : auditNote;
117	
118	  return await prisma.order.update({
119	    where: { id: orderId },
120	    data: {
121	      status: newStatus,
122	      notes: existingNotes,
123	    },
124	  });
125	}
